-- Explicit initial week only; weekday templates do not automatically open future sales.
CREATE TABLE IF NOT EXISTS daily_lunch_config (id INTEGER PRIMARY KEY CHECK(id=1), config_json TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, updated_at INTEGER NOT NULL, updated_by TEXT);
INSERT OR IGNORE INTO daily_lunch_config (id,config_json,version,updated_at,updated_by) VALUES (1,'{"products": [{"id": "fried_rice", "name": "Añejo Fried Rice", "description": "A generous bowl of house fried rice with chicken, ham, bacon, egg, vegetables and green onions, served with Añejo Sauce. Approximately 16–17 oz prepared meal.", "image_url": null}, {"id": "chicken_quesadillas", "name": "Añejo Chicken Quesadillas", "description": "Chicken and melted cheese quesadillas served with golden fries, house coleslaw and Añejo Sauce.", "image_url": null}, {"id": "pechuguitas", "name": "Pechuguitas de la Abuela", "description": "Grandma’s crispy seasoned chicken pechuguitas served with golden fries, fresh house salad and Añejo Sauce. A family recipe, made the Añejo way.", "image_url": null}, {"id": "papa", "name": "Papa Añejo", "description": "A large baked potato loaded with seasoned beef and melted cheese, finished with Añejo crema and served with fresh greens and crunchy chips.", "image_url": null}], "settings": {"same_day_cutoff": "11:00", "preorder_cutoff": "19:00"}, "weekdays": [{"dow": 1, "product_id": "fried_rice", "enabled": true}, {"dow": 2, "product_id": "chicken_quesadillas", "enabled": true}, {"dow": 3, "product_id": "pechuguitas", "enabled": true}, {"dow": 4, "product_id": "papa", "enabled": true}], "dates": [{"date": "2026-09-28", "product_id": "fried_rice", "enabled": true, "sold_out": false}, {"date": "2026-09-29", "product_id": "chicken_quesadillas", "enabled": true, "sold_out": false}, {"date": "2026-09-30", "product_id": "pechuguitas", "enabled": true, "sold_out": false}, {"date": "2026-10-01", "product_id": "papa", "enabled": true, "sold_out": false}]}',1,0,'migration:0140');
